    function cleanBase64(base64) {
      const cleaned = String(base64)
        .replace(
          /^data:application\/pdf(?:;[^,]*)?;base64,/i,
          ""
        )
        .replace(/\s/g, "");

      if (
        !cleaned ||
        cleaned.includes("PASTE_COMBINED_PDF")
      ) {
        throw new Error(
          "The combined PDF Base64 placeholder has not been replaced."
        );
      }

      return cleaned;
    }

    function base64ToBytes(base64) {
      const cleaned = cleanBase64(base64);
      const binary = atob(cleaned);
      const bytes = new Uint8Array(binary.length);

      for (let i = 0; i < binary.length; i += 1) {
        bytes[i] = binary.charCodeAt(i);
      }

      return bytes;
    }

    function loadExternalScript(src) {
      return new Promise((resolve, reject) => {
        const script = document.createElement("script");
        script.src = src;
        script.onload = resolve;
        script.onerror = () => {
          reject(new Error(`Could not load ${src}`));
        };
        document.head.appendChild(script);
      });
    }

    async function ensurePdfLib() {
      if (window.PDFLib) {
        return;
      }

      const fallbacks = [
        "js/pdf.js",
        "https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js",
        "https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js"
      ];

      for (const src of fallbacks) {
        try {
          await loadExternalScript(src);

          if (window.PDFLib) {
            return;
          }
        } catch (error) {
          console.warn(error);
        }
      }

      throw new Error(
        "The PDF engine could not load on this browser. Keep this HTML file together with the js folder, or open it while connected to the internet and try again."
      );
    }

    async function loadPdfFromBase64(base64) {
      await ensurePdfLib();

      const bytes = base64ToBytes(base64);

      return PDFLib.PDFDocument.load(bytes);
    }

