    async function generateCombinedPacket() {
      const generateButton =
        document.getElementById("generateButton");

      generateButton.disabled = true;

      try {
        const data = collectFormData();
        validateRequiredData(data);

        const missingFormFields = getMissingGenerateFields(data);

        if (!(await confirmMissingGenerateFields(missingFormFields))) {
          const first = document.getElementById(
            missingFormFields[0].elementId
          );

          if (first) {
            first.focus();
            first.scrollIntoView({
              behavior: "smooth",
              block: "center"
            });
          }

          setStatus(
            "Generate cancelled. Edit the missing fields and try again.",
            "warning"
          );
          return;
        }

        setStatus("Generating the editable two-page packet...");

        const missingFields = [];

        /*
          Each click loads a fresh copy of the supplied combined
          template. Keeping both pages in one document preserves its
          AcroForm field tree and lets every final field remain editable.
        */
        const combinedPdf =
          await loadPdfFromBase64(
            COMBINED_PDF_BASE64
          );

        await fillMedicalPdf(
          combinedPdf,
          data,
          missingFields
        );

        await fillCapPage(
          combinedPdf,
          data,
          missingFields
        );

        const combinedPdfBytes =
          await combinedPdf.save({
            updateFieldAppearances: false,
            useObjectStreams: true
          });

        const filename = buildBookInFilename(data);

        downloadPdf(
          combinedPdfBytes,
          filename
        );

        if (missingFields.length > 0) {
          setStatus(
            `The packet was generated, but these PDF fields could not be found:\n\n${missingFields.join("\n")}`,
            "warning"
          );
        } else {
          setStatus(
           `For the Republic. \nDocuments generated successfully:${filename}`,
  "success"
          );
        }

      } catch (error) {
        console.error(error);

        setStatus(
          `Error: ${error.message}`,
          "error"
        );

      } finally {
        generateButton.disabled = false;
      }
    }

    function isMobileBrowser() {
      return /Android|iPhone|iPad|iPod/i.test(navigator.userAgent) ||
        (
          navigator.platform === "MacIntel" &&
          navigator.maxTouchPoints > 1
        );
    }

    function downloadPdf(pdfBytes, filename) {
      const blob = new Blob(
        [pdfBytes],
        {
          type: "application/pdf"
        }
      );

      const url = URL.createObjectURL(blob);

      if (isMobileBrowser()) {
        const opened = window.open(url, "_blank");

        if (!opened) {
          window.location.assign(url);
        }

        return;
      }

      const link = document.createElement("a");

      link.href = url;
      link.download = filename;

      document.body.appendChild(link);
      link.click();
      link.remove();

      setTimeout(() => {
        URL.revokeObjectURL(url);
      }, 1500);
    }

    function setDefaultDateTime() {
      const input =
        document.getElementById("dateTime");

      const now = new Date();

      const timezoneOffset =
        now.getTimezoneOffset() * 60000;

      const localDate =
        new Date(now.getTime() - timezoneOffset);

      input.value =
        localDate.toISOString().slice(0, 16);
    }

    function setDefaultTeam() {
      const input = document.getElementById("team");

      if (input && !String(input.value || "").trim()) {
        input.value = DEFAULT_TEAM;
      }
    }

    function confirmClearForm() {
      const dialog = document.getElementById("clearConfirmDialog");
      const ok = document.getElementById("clearConfirmOk");
      const cancel = document.getElementById("clearConfirmCancel");

      if (!dialog || !ok || !cancel) {
        if (
          window.confirm(
            "Clear the form? Saved records are not deleted."
          )
        ) {
          clearForm();
        }
        return;
      }

      dialog.hidden = false;
      cancel.focus();

      function finish(shouldClear) {
        dialog.hidden = true;
        ok.removeEventListener("click", onOk);
        cancel.removeEventListener("click", onCancel);
        dialog.removeEventListener("click", onBackdrop);
        document.removeEventListener("keydown", onKeyDown);
        if (shouldClear) {
          clearForm();
        }
      }

      function onOk() {
        finish(true);
      }

      function onCancel() {
        finish(false);
      }

      function onBackdrop(event) {
        if (event.target === dialog) {
          finish(false);
        }
      }

      function onKeyDown(event) {
        if (event.key === "Escape") {
          event.preventDefault();
          finish(false);
        }
      }

      ok.addEventListener("click", onOk);
      cancel.addEventListener("click", onCancel);
      dialog.addEventListener("click", onBackdrop);
      document.addEventListener("keydown", onKeyDown);
    }

    function isAutoSaveField(element) {
      if (!element || !element.matches) {
        return false;
      }
      if (element.dataset.recordIgnore === "true") {
        return false;
      }
      if (
        element.matches(
          'input[type="button"], input[type="submit"], input[type="file"], button'
        )
      ) {
        return false;
      }
      return element.matches("input, select, textarea");
    }

    function requestAutoSave() {
      if (suppressAutoSave) {
        return;
      }
      window.setTimeout(function () {
        if (suppressAutoSave) {
          return;
        }
        if (currentFormSignature() === lastSavedSignature) {
          return;
        }
        saveCurrentRecord({ quiet: true });
      }, 0);
    }

    function bindBookInAutoSave() {
      if (autoSaveBound) {
        return;
      }
      autoSaveBound = true;
      document.addEventListener(
        "focusout",
        function (event) {
          if (isAutoSaveField(event.target)) {
            requestAutoSave();
          }
        },
        true
      );
      document.addEventListener("change", function (event) {
        if (isAutoSaveField(event.target)) {
          requestAutoSave();
        }
      });
    }

    function clearForm(options) {
      const quiet = Boolean(options && options.quiet);
      suppressAutoSave = true;
      document
        .querySelectorAll(
          'select option[data-legacy-value="true"]'
        )
        .forEach(option => option.remove());

      document
        .querySelectorAll(
          "input:not([readonly]), textarea, select"
        )
        .forEach(element => {
          if (element.dataset.recordIgnore === "true") {
            return;
          }

          if (element.matches('input[type="radio"], input[type="checkbox"]')) {
            element.checked = false;
          } else {
            element.value = "";
          }

          element.classList.remove("invalid-field");
        });

      updateAge();

      activeRecordId = null;

      setDefaultDateTime();
      setDefaultTeam();
      updateGenderLogic();
      renderSavedRecords();
      rememberFormSignature();
      if (!quiet) {
        suppressAutoSave = false;
        setStatus("All form fields cleared.");
      }
    }

